// Rule: accessible-authentication
window.NativeEngine.addRule({
  id: "accessible-authentication",
  impact: "critical",
  description: "Authentication must not require a cognitive function test without an accessible alternative.",
  help: "Ensure CAPTCHAs provide an audio alternative, object recognition alternative, or personal content alternative.",
  helpUrl: "https://www.w3.org/WAI/WCAG22/Understanding/accessible-authentication-minimum.html",
  tags: ["wcag22aa","wcag338"],
  evaluate: function(document) {
    var violations = [];
    var passes = [];
    var incomplete = [];

    // Known CAPTCHA provider domains — extend this list as new providers emerge
    var CAPTCHA_DOMAINS = [
      'recaptcha.net',
      'google.com/recaptcha',
      'gstatic.com/recaptcha',
      'js.hcaptcha.com',
      'hcaptcha.com',
      'challenges.cloudflare.com',
      'turnstile.cloudflare.com',
      'funcaptcha.com',
      'arkoselabs.com',
      'captcha-delivery.com',
      'friendly-captcha.com',
      'mtcaptcha.com',
      'procaptcha.com'
    ];

    function matchesCaptchaDomain(src) {
      if (!src) return false;
      var lower = src.toLowerCase();
      for (var i = 0; i < CAPTCHA_DOMAINS.length; i++) {
        if (lower.indexOf(CAPTCHA_DOMAINS[i]) !== -1) return true;
      }
      return false;
    }

    var captchaFound = false;
    var captchaSource = '';
    var captchaHtml = '';

    // Layer 1: script src
    var scripts = Array.from(document.querySelectorAll('script[src]'));
    for (var si = 0; si < scripts.length; si++) {
      var scriptSrc = scripts[si].getAttribute('src') || '';
      if (matchesCaptchaDomain(scriptSrc)) {
        captchaFound = true;
        captchaSource = scriptSrc.substring(0, 80);
        captchaHtml = '<script src="' + captchaSource + '">';
        break;
      }
    }

    // Layer 2: iframe src
    if (!captchaFound) {
      var iframes = Array.from(document.querySelectorAll('iframe[src]'));
      for (var ii = 0; ii < iframes.length; ii++) {
        var iframeSrc = iframes[ii].getAttribute('src') || '';
        if (matchesCaptchaDomain(iframeSrc)) {
          captchaFound = true;
          captchaSource = iframeSrc.substring(0, 80);
          captchaHtml = iframes[ii].outerHTML.substring(0, 120);
          break;
        }
      }
    }

    // Layer 3: <img> inside <form> with captcha in alt or src
    if (!captchaFound) {
      var forms = Array.from(document.querySelectorAll('form'));
      for (var fi = 0; fi < forms.length; fi++) {
        var imgs = Array.from(forms[fi].querySelectorAll('img'));
        for (var imi = 0; imi < imgs.length; imi++) {
          var alt = (imgs[imi].getAttribute('alt') || '').toLowerCase();
          var imgSrc = (imgs[imi].getAttribute('src') || '').toLowerCase();
          var cls = (imgs[imi].className && typeof imgs[imi].className === 'string'
            ? imgs[imi].className : '').toLowerCase();
          if (alt.indexOf('captcha') !== -1 || imgSrc.indexOf('captcha') !== -1 ||
              cls.indexOf('captcha') !== -1) {
            captchaFound = true;
            captchaHtml = imgs[imi].outerHTML.substring(0, 120);
            captchaSource = 'captcha image inside form';
            break;
          }
        }
        if (captchaFound) break;
      }
    }

    if (captchaFound) {
      violations.push({
        html: captchaHtml,
        target: ['form'],
        failureSummary: 'CAPTCHA or cognitive function test detected (' + captchaSource + '). Verify an accessible alternative exists: (1) audio CAPTCHA, (2) object recognition test, (3) personal-content test, or (4) an authentication method that does not use CAPTCHAs at all.'
      });
      return { violations: violations, passes: passes, incomplete: incomplete };
    }

    // Layer 4: class/id heuristic — less certain, emit incomplete
    var captchaWidgets = Array.from(document.querySelectorAll(
      '[class*="captcha"], [id*="captcha"], [data-sitekey], [data-widget-type="captcha"]'
    ));
    if (captchaWidgets.length > 0) {
      incomplete.push({
        html: captchaWidgets[0].outerHTML.substring(0, 120),
        target: [captchaWidgets[0].tagName.toLowerCase()],
        failureSummary: 'Element with CAPTCHA-related class, id, or data-sitekey attribute detected. Manually verify whether a cognitive function test is required without an accessible alternative.'
      });
      return { violations: violations, passes: passes, incomplete: incomplete };
    }

    // Check whether any authentication form exists at all; if not, SC is not applicable
    var authForms = Array.from(document.querySelectorAll('form')).filter(function(f) {
      var inputs = Array.from(f.querySelectorAll('input'));
      return inputs.some(function(inp) {
        return inp.getAttribute('type') === 'password';
      });
    });

    if (authForms.length > 0) {
      passes.push({
        html: authForms[0].outerHTML.substring(0, 120),
        target: ['form']
      });
    } else {
      passes.push({ html: '<body>', target: ['body'] });
    }

    return { violations: violations, passes: passes, incomplete: incomplete };
  }
});

// Rule: accesskeys
window.NativeEngine.addRule({
  id: "accesskeys",
  impact: "serious",
  description: "Every accesskey attribute value must be unique.",
  help: "Ensure that accesskey attribute values are unique.",
  helpUrl: "https://www.w3.org/WAI/WCAG21/Understanding/keyboard.html",
  tags: ["wcag211","best-practice"],
  evaluate: function(document) {
    const violations = [];
    const passes = [];
    const incomplete = [];
    
    const elementsWithAccessKey = Array.from(document.querySelectorAll('*[accesskey]'));
    const keyMap = {};
    
    elementsWithAccessKey.forEach(el => {
      const keys = el.getAttribute('accesskey').trim().toLowerCase().split(/\s+/);
      keys.forEach(k => {
        if (!keyMap[k]) keyMap[k] = [];
        keyMap[k].push(el);
      });
    });
    
    elementsWithAccessKey.forEach(el => {
      const keys = el.getAttribute('accesskey').trim().toLowerCase().split(/\s+/);
      let isDuplicate = false;
      let dupKey = null;
      
      for (const k of keys) {
        if (keyMap[k].length > 1) {
          isDuplicate = true;
          dupKey = k;
          break;
        }
      }
      
      if (isDuplicate) {
        violations.push({
          html: el.outerHTML.substring(0, 100),
          target: [el.tagName.toLowerCase()],
          failureSummary: `The accesskey "${dupKey}" is not unique on the page.`
        });
      } else {
        passes.push({ html: el.outerHTML.substring(0, 100), target: [el.tagName.toLowerCase()] });
      }
    });
    
    return { violations, passes, incomplete };
  }
});

// Rule: aria-allowed-attr
window.NativeEngine.addRule({
  id: "aria-allowed-attr",
  impact: "critical",
  description: "ARIA attributes must be valid for the role they are used on.",
  help: "Ensure ARIA attributes are allowed for an element's role.",
  helpUrl: "https://www.w3.org/WAI/WCAG21/Understanding/name-role-value.html",
  tags: ["wcag412"],
  evaluate: function(document) {
    const violations = [];
    const passes = [];
    const incomplete = [];
    
    // Global attributes are allowed on almost all elements
    const globalAria = new Set([
      'aria-atomic', 'aria-busy', 'aria-controls', 'aria-current', 'aria-describedby',
      'aria-details', 'aria-disabled', 'aria-dropeffect', 'aria-errormessage', 'aria-flowto',
      'aria-grabbed', 'aria-haspopup', 'aria-hidden', 'aria-invalid', 'aria-keyshortcuts',
      'aria-label', 'aria-labelledby', 'aria-live', 'aria-owns', 'aria-relevant',
      'aria-roledescription'
    ]);
    
    // Mapping of restricted attributes to roles they are allowed on (simplified heuristic)
    const allowedMap = {
      'aria-checked': ['checkbox', 'menuitemcheckbox', 'option', 'radio', 'menuitemradio', 'switch', 'treeitem'],
      'aria-pressed': ['button'],
      'aria-expanded': ['button', 'combobox', 'document', 'link', 'row', 'rowheader', 'treeitem', 'window', 'application', 'checkbox', 'menuitem', 'menuitemcheckbox', 'menuitemradio', 'tab'],
      'aria-required': ['checkbox', 'combobox', 'gridcell', 'listbox', 'radiogroup', 'spinbutton', 'textbox', 'tree', 'columnheader', 'rowheader'],
      'aria-selected': ['cell', 'columnheader', 'gridcell', 'option', 'row', 'rowheader', 'tab', 'treeitem'],
      'aria-level': ['heading', 'listitem', 'row', 'treeitem'],
      'aria-valuemax': ['scrollbar', 'separator', 'slider', 'spinbutton', 'meter', 'progressbar'],
      'aria-valuemin': ['scrollbar', 'separator', 'slider', 'spinbutton', 'meter', 'progressbar'],
      'aria-valuenow': ['scrollbar', 'separator', 'slider', 'spinbutton', 'meter', 'progressbar'],
      'aria-valuetext': ['scrollbar', 'separator', 'slider', 'spinbutton', 'meter', 'progressbar'],
      'aria-autocomplete': ['combobox', 'searchbox', 'textbox']
    };
    
    const elementsWithAria = Array.from(document.querySelectorAll('*'));
    
    elementsWithAria.forEach(el => {
      let role = el.getAttribute('role');
      if (!role) {
        // Native fallback mapping could go here (e.g. <input type="checkbox"> -> checkbox)
        // For simplicity, we only strictly validate against explicit roles if present.
        return;
      }
      role = role.split(/\s+/)[0].toLowerCase();
      
      let hasAria = false;
      let invalidAttr = null;
      
      for (let i = 0; i < el.attributes.length; i++) {
        const attrName = el.attributes[i].name.toLowerCase();
        if (attrName.startsWith('aria-') && !globalAria.has(attrName)) {
          hasAria = true;
          const allowedRoles = allowedMap[attrName];
          if (allowedRoles && !allowedRoles.includes(role)) {
            invalidAttr = attrName;
            break;
          }
        }
      }
      
      if (hasAria) {
        if (invalidAttr) {
          violations.push({
            html: el.outerHTML.substring(0, 100),
            target: [el.tagName.toLowerCase()],
            failureSummary: `The attribute "${invalidAttr}" is not allowed on an element with role="${role}".`
          });
        } else {
          passes.push({ html: el.outerHTML.substring(0, 100), target: [el.tagName.toLowerCase()] });
        }
      }
    });
    
    return { violations, passes, incomplete };
  }
});

// Rule: aria-allowed-role
window.NativeEngine.addRule({
  id: "aria-allowed-role",
  impact: "minor",
  description: "ARIA role should be appropriate for the element.",
  help: "Ensure role attribute has an appropriate value for the element.",
  helpUrl: "https://www.w3.org/WAI/WCAG21/Understanding/name-role-value.html",
  tags: ["wcag412"],
  evaluate: function(document) {
    const violations = [];
    const passes = [];
    const incomplete = [];
    
    // Heuristics for elements that shouldn't have arbitrary roles
    // For example, heading elements should usually stay headings or presentation.
    const strictElements = {
      'h1': ['heading', 'presentation', 'none', 'tab'],
      'h2': ['heading', 'presentation', 'none', 'tab'],
      'h3': ['heading', 'presentation', 'none', 'tab'],
      'h4': ['heading', 'presentation', 'none', 'tab'],
      'h5': ['heading', 'presentation', 'none', 'tab'],
      'h6': ['heading', 'presentation', 'none', 'tab'],
      'ul': ['directory', 'group', 'list', 'listbox', 'menu', 'menubar', 'radiogroup', 'tablist', 'toolbar', 'tree', 'presentation', 'none'],
      'ol': ['directory', 'group', 'list', 'listbox', 'menu', 'menubar', 'radiogroup', 'tablist', 'toolbar', 'tree', 'presentation', 'none'],
      'dl': ['group', 'list', 'presentation', 'none'],
      'fieldset': ['group', 'radiogroup', 'presentation', 'none'],
      'legend': [], // generally should not have roles
    };
    
    const elementsWithRole = Array.from(document.querySelectorAll('*[role]'));
    
    elementsWithRole.forEach(el => {
      const tag = el.tagName.toLowerCase();
      const allowedRoles = strictElements[tag];
      
      if (allowedRoles) {
        const roleAttr = el.getAttribute('role').trim().toLowerCase();
        const roles = roleAttr.split(/\s+/);
        let hasInvalidRole = false;
        let badRole = null;
        
        for (const role of roles) {
          if (!allowedRoles.includes(role)) {
            hasInvalidRole = true;
            badRole = role;
            break;
          }
        }
        
        if (hasInvalidRole) {
          violations.push({
            html: el.outerHTML.substring(0, 100),
            target: [tag],
            failureSummary: `The role "${badRole}" is not allowed for <${tag}> elements.`
          });
          return;
        }
      }
      
      passes.push({ html: el.outerHTML.substring(0, 100), target: [el.tagName.toLowerCase()] });
    });
    
    return { violations, passes, incomplete };
  }
});

// Rule: aria-conditional-attr
window.NativeEngine.addRule({
  id: "aria-conditional-attr",
  impact: "serious",
  description: "Conditional ARIA attributes must be used correctly.",
  help: "Ensure ARIA attributes are used as per their conditional requirements.",
  helpUrl: "https://www.w3.org/WAI/WCAG21/Understanding/name-role-value.html",
  tags: ["wcag412"],
  evaluate: function(document) {
    const violations = [];
    const passes = [];
    const incomplete = [];
    
    // Heuristic 1: aria-errormessage should ideally be accompanied by aria-invalid="true"
    const errorElements = Array.from(document.querySelectorAll('*[aria-errormessage]'));
    
    errorElements.forEach(el => {
      const invalid = el.getAttribute('aria-invalid');
      if (invalid === 'true' || invalid === 'spelling' || invalid === 'grammar') {
        passes.push({ html: el.outerHTML.substring(0, 100), target: [el.tagName.toLowerCase()] });
      } else {
        violations.push({
          html: el.outerHTML.substring(0, 100),
          target: [el.tagName.toLowerCase()],
          failureSummary: 'Element has aria-errormessage but is not marked as aria-invalid="true".'
        });
      }
    });
    
    return { violations, passes, incomplete };
  }
});

