// Rule: landmark-one-main
window.NativeEngine.addRule({
  id: "landmark-one-main",
  impact: "moderate",
  description: "Document must have one main landmark.",
  help: "Ensure the page has exactly one main landmark.",
  helpUrl: "https://www.w3.org/WAI/WCAG21/Understanding/info-and-relationships.html",
  tags: ["wcag131"],
  evaluate: function(document) {
    const violations = [];
    const passes = [];
    const incomplete = [];
    
    const mains = Array.from(document.querySelectorAll('main, *[role="main"]'));
    
    if (mains.length === 0) {
      violations.push({
        html: 'N/A',
        target: ['html'],
        failureSummary: 'Document does not have a main landmark.'
      });
    } else if (mains.length === 1) {
      passes.push({ html: mains[0].outerHTML.substring(0, 100), target: [mains[0].tagName.toLowerCase()] });
    } else {
      // Handled by landmark-no-duplicate-main, but we can also fail here or leave it. Axe fails it here too.
      violations.push({
        html: 'N/A',
        target: ['html'],
        failureSummary: `Document has multiple (${mains.length}) main landmarks.`
      });
    }
    
    return { violations, passes, incomplete };
  }
});

// Rule: landmark-unique
window.NativeEngine.addRule({
  id: "landmark-unique",
  impact: "moderate",
  description: "Landmarks must have a unique role or role/label/title combination.",
  help: "Ensure landmarks are unique.",
  helpUrl: "https://www.w3.org/WAI/WCAG21/Understanding/info-and-relationships.html",
  tags: ["wcag131"],
  evaluate: function(document) {
    const violations = [];
    const passes = [];
    const incomplete = [];
    
    // Core landmark roles
    const landmarkRoles = ['banner', 'complementary', 'contentinfo', 'form', 'main', 'navigation', 'region', 'search'];
    
    // Find all landmarks
    const landmarks = [];
    
    const elements = Array.from(document.querySelectorAll('*'));
    elements.forEach(el => {
      const tag = el.tagName.toLowerCase();
      let role = el.getAttribute('role');
      
      if (!role) {
        if (tag === 'header') role = 'banner';
        if (tag === 'footer') role = 'contentinfo';
        if (tag === 'main') role = 'main';
        if (tag === 'nav') role = 'navigation';
        if (tag === 'aside') role = 'complementary';
        if (tag === 'section' && (el.hasAttribute('aria-label') || el.hasAttribute('aria-labelledby'))) role = 'region';
        if (tag === 'form' && (el.hasAttribute('aria-label') || el.hasAttribute('aria-labelledby'))) role = 'form';
      }
      
      if (role && landmarkRoles.includes(role)) {
        // Compute accessible name
        let name = el.getAttribute('aria-label') || '';
        if (!name && el.hasAttribute('aria-labelledby')) {
          const ids = el.getAttribute('aria-labelledby').split(/\s+/);
          name = ids.map(id => {
            const ref = document.getElementById(id);
            return ref ? ref.textContent : '';
          }).join(' ');
        }
        if (!name) name = el.getAttribute('title') || '';
        
        landmarks.push({ el, role, name: name.trim() });
      }
    });
    
    // Check for duplicates
    const counts = {};
    landmarks.forEach(lm => {
      const key = `${lm.role}::${lm.name}`;
      counts[key] = (counts[key] || 0) + 1;
    });
    
    landmarks.forEach(lm => {
      const key = `${lm.role}::${lm.name}`;
      if (counts[key] > 1) {
        violations.push({
          html: lm.el.outerHTML.substring(0, 100),
          target: [lm.el.tagName.toLowerCase()],
          failureSummary: `Landmark has the same role ("${lm.role}") and name ("${lm.name}") as another landmark.`
        });
      } else {
        passes.push({ html: lm.el.outerHTML.substring(0, 100), target: [lm.el.tagName.toLowerCase()] });
      }
    });
    
    return { violations, passes, incomplete };
  }
});

// Rule: link-name
window.NativeEngine.addRule({
  id: "link-name",
  impact: "critical",
  description: "Links must have discernible text.",
  help: "Ensure links have an accessible name.",
  helpUrl: "https://www.w3.org/WAI/WCAG21/Understanding/link-purpose-in-context.html",
  tags: ["wcag244"],
  evaluate: function(document) {
    const violations = [];
    const passes = [];
    const incomplete = [];
    
    const links = Array.from(document.querySelectorAll('a[href], *[role="link"]'));
    
    links.forEach(el => {
      let hasName = false;
      
      const text = el.textContent.trim();
      const ariaLabel = (el.getAttribute('aria-label') || '').trim();
      const ariaLabelledBy = (el.getAttribute('aria-labelledby') || '').trim();
      const title = (el.getAttribute('title') || '').trim();
      
      const hasImgWithAlt = Array.from(el.querySelectorAll('img[alt]')).some(img => img.getAttribute('alt').trim().length > 0);
      
      if (text.length > 0 || ariaLabel.length > 0 || ariaLabelledBy.length > 0 || title.length > 0 || hasImgWithAlt) {
        hasName = true;
      }
      
      if (hasName) {
        passes.push({ html: el.outerHTML.substring(0, 100), target: [el.tagName.toLowerCase()] });
      } else {
        violations.push({
          html: el.outerHTML.substring(0, 100),
          target: [el.tagName.toLowerCase()],
          failureSummary: 'Link is empty and has no accessible name.'
        });
      }
    });
    
    return { violations, passes, incomplete };
  }
});

// Rule: list
window.NativeEngine.addRule({
  id: "list",
  impact: "serious",
  description: "Lists must be structured properly.",
  help: "Ensure that lists are structured correctly.",
  helpUrl: "https://www.w3.org/WAI/WCAG21/Understanding/info-and-relationships.html",
  tags: ["wcag131"],
  evaluate: function(document) {
    const violations = [];
    const passes = [];
    const incomplete = [];
    
    const lists = Array.from(document.querySelectorAll('ul, ol, dl, *[role="list"]'));
    
    lists.forEach(list => {
      const tag = list.tagName.toLowerCase();
      const role = list.getAttribute('role');
      let isValid = true;
      
      const children = Array.from(list.children);
      
      if (tag === 'ul' || tag === 'ol' || role === 'list') {
        // Only allow li, script, template
        for (const child of children) {
          const ctag = child.tagName.toLowerCase();
          if (ctag !== 'li' && ctag !== 'script' && ctag !== 'template' && child.getAttribute('role') !== 'listitem') {
            isValid = false;
            break;
          }
        }
      } else if (tag === 'dl') {
        // Allow dt, dd, div (which can contain dt/dd), script, template
        for (const child of children) {
          const ctag = child.tagName.toLowerCase();
          if (ctag !== 'dt' && ctag !== 'dd' && ctag !== 'div' && ctag !== 'script' && ctag !== 'template') {
            isValid = false;
            break;
          }
        }
      }
      
      if (isValid) {
        passes.push({ html: list.outerHTML.substring(0, 100), target: [tag] });
      } else {
        violations.push({
          html: list.outerHTML.substring(0, 100),
          target: [tag],
          failureSummary: 'List element contains invalid children. UL/OL should only contain LI; DL should only contain DT/DD/DIV.'
        });
      }
    });
    
    return { violations, passes, incomplete };
  }
});

// Rule: listitem
window.NativeEngine.addRule({
  id: "listitem",
  impact: "serious",
  description: "List items must be contained within lists.",
  help: "Ensure that list items are contained within appropriate lists.",
  helpUrl: "https://www.w3.org/WAI/WCAG21/Understanding/info-and-relationships.html",
  tags: ["wcag131"],
  evaluate: function(document) {
    const violations = [];
    const passes = [];
    const incomplete = [];
    
    const items = Array.from(document.querySelectorAll('li, dt, dd, *[role="listitem"]'));
    
    items.forEach(item => {
      const tag = item.tagName.toLowerCase();
      const role = item.getAttribute('role');
      
      let isValid = false;
      let parent = item.parentElement;
      
      if (tag === 'li' || role === 'listitem') {
        while (parent && parent.tagName.toLowerCase() !== 'body') {
          const ptag = parent.tagName.toLowerCase();
          const prole = parent.getAttribute('role');
          if (ptag === 'ul' || ptag === 'ol' || prole === 'list') {
            isValid = true;
            break;
          }
          parent = parent.parentElement;
        }
      } else if (tag === 'dt' || tag === 'dd') {
        while (parent && parent.tagName.toLowerCase() !== 'body') {
          if (parent.tagName.toLowerCase() === 'dl') {
            isValid = true;
            break;
          }
          parent = parent.parentElement;
        }
      }
      
      if (isValid) {
        passes.push({ html: item.outerHTML.substring(0, 100), target: [tag] });
      } else {
        violations.push({
          html: item.outerHTML.substring(0, 100),
          target: [tag],
          failureSummary: 'List item is not contained within an appropriate list element (ul, ol, or dl).'
        });
      }
    });
    
    return { violations, passes, incomplete };
  }
});

